--!strict

local RbxLinearSpring = require(script.Parent.RbxLinearSpring)
local RotationSpring = require(script.Parent.Primitives.RotationSpring)

local CFrameSpringClass = {}
CFrameSpringClass.__index = CFrameSpringClass
CFrameSpringClass.ClassName = "CFrameSpring"

export type CFrameSpring = typeof(setmetatable(
	{} :: {
		posInternal: RbxLinearSpring.RbxLinearSpring<Vector3>,
		rotInternal: RotationSpring.RotationSpring,
	},
	CFrameSpringClass
))

-- Constructors

function CFrameSpringClass.new(dampingRatio: number, frequency: number, position: CFrame, goal: CFrame)
	local self = setmetatable({}, CFrameSpringClass) :: CFrameSpring

	self.posInternal = RbxLinearSpring.new(dampingRatio, frequency, position.Position, goal.Position)
	self.rotInternal = RotationSpring.new(dampingRatio, frequency, position.Rotation, goal.Rotation)

	return self
end

-- Public Methods

function CFrameSpringClass.getDampingRatio(self: CFrameSpring)
	return self.posInternal:getDampingRatio()
end

function CFrameSpringClass.getFrequency(self: CFrameSpring)
	return self.posInternal:getFrequency()
end

function CFrameSpringClass.getPosition(self: CFrameSpring)
	local pos = self.posInternal:getPosition()
	local rot = self.rotInternal:getPosition()

	return CFrame.new(pos) * rot
end

function CFrameSpringClass.getVelocity(self: CFrameSpring)
	local pVel = self.posInternal:getVelocity()
	local rVel = self.rotInternal:getVelocity()

	return { pVel[1], pVel[2], pVel[3], rVel.X, rVel.Y, rVel.Z }
end

function CFrameSpringClass.getGoal(self: CFrameSpring)
	local pos = self.posInternal:getGoal()
	local rot = self.rotInternal:getGoal()

	return CFrame.new(pos) * rot
end

function CFrameSpringClass.setDampingRatio(self: CFrameSpring, dampingRatio: number)
	self.posInternal:setDampingRatio(dampingRatio)
	self.rotInternal:setDampingRatio(dampingRatio)
end

function CFrameSpringClass.setFrequency(self: CFrameSpring, frequency: number)
	self.posInternal:setFrequency(frequency)
	self.rotInternal:setFrequency(frequency)
end

function CFrameSpringClass.setPosition(self: CFrameSpring, position: CFrame)
	self.posInternal:setPosition(position.Position)
	self.rotInternal:setPosition(position.Rotation)
end

function CFrameSpringClass.setVelocity(self: CFrameSpring, velocity: { number })
	self.posInternal:setVelocity({ velocity[1], velocity[2], velocity[3] })
	self.rotInternal:setVelocity(Vector3.new(velocity[4], velocity[5], velocity[6]))
end

function CFrameSpringClass.setGoal(self: CFrameSpring, goal: CFrame)
	self.posInternal:setGoal(goal.Position)
	self.rotInternal:setGoal(goal.Rotation)
end

function CFrameSpringClass.canSleep(self: CFrameSpring)
	return self.posInternal:canSleep() and self.rotInternal:canSleep()
end

function CFrameSpringClass.step(self: CFrameSpring, dt: number)
	local pos = self.posInternal:step(dt)
	local rot = self.rotInternal:step(dt)

	return CFrame.new(pos) * rot
end

--

return CFrameSpringClass

--!strict

local RbxLinearSpring = require(script.RbxLinearSpring)
local CFrameSpring = require(script.CFrameSpring)

--[=[
	@class FractalitySpring

	A high-performance fully typed spring class based on Fractality's spr library for use in Roblox.

	Visualizer: https://www.desmos.com/calculator/rzvw27ljh9
]=]

local FractalitySpringClass = {}
FractalitySpringClass.__index = FractalitySpringClass
FractalitySpringClass.ClassName = "FractalitySpring"

export type Supported = RbxLinearSpring.Supported | CFrame

export type FractalitySpring<T> = typeof(setmetatable(
	{} :: {
		internal: RbxLinearSpring.RbxLinearSpring<T>,
	},
	FractalitySpringClass
))

export type Spring<T> = FractalitySpring<T>

-- Constructors

--[=[
	@within FractalitySpring
	@function new

	Creates a new spring.

	Supports the following types:
	boolean, number, NumberRange, UDim, UDim2, Vector2, Vector3, Color3, CFrame

	@param dampingRation number
	@param frequency number
	@param position T
	@param goal T
	@return FractalitySpring<T>
]=]
function FractalitySpringClass.new<T>(
	dampingRatio: number,
	frequency: number,
	position: T & Supported,
	goal: T & Supported
)
	local self = setmetatable({}, FractalitySpringClass) :: FractalitySpring<T>

	if typeof(position) == "CFrame" then
		self.internal = (
			CFrameSpring.new(dampingRatio, frequency, position, goal) :: any
		) :: RbxLinearSpring.RbxLinearSpring<T>
	else
		local supportedPos = (position :: any) :: RbxLinearSpring.Supported
		local supportedGoal = (goal :: any) :: RbxLinearSpring.Supported
		self.internal = RbxLinearSpring.new(dampingRatio, frequency, supportedPos, supportedGoal)
	end

	return self
end

-- Public Methods

--[=[
	@within FractalitySpring
	@method getDampingRatio

	Returns the spring's current damping ratio value.

	@return number
]=]
function FractalitySpringClass.getDampingRatio<T>(self: FractalitySpring<T>)
	return self.internal:getDampingRatio()
end

--[=[
	@within FractalitySpring
	@method getFrequency

	Returns the spring's current frequency value.

	@return number
]=]
function FractalitySpringClass.getFrequency<T>(self: FractalitySpring<T>)
	return self.internal:getFrequency()
end

--[=[
	@within FractalitySpring
	@method getPosition

	Returns the spring's current position.

	@return T
]=]
function FractalitySpringClass.getPosition<T>(self: FractalitySpring<T>)
	return self.internal:getPosition()
end

--[=[
	@within FractalitySpring
	@method getVelocity

	Returns the spring's current velocity. The length of this array depends on the value type of the spring.

	@return { number }
]=]
function FractalitySpringClass.getVelocity<T>(self: FractalitySpring<T>)
	return self.internal:getVelocity()
end

--[=[
	@within FractalitySpring
	@method getGoal

	Returns the spring's current goal.

	@return T
]=]
function FractalitySpringClass.getGoal<T>(self: FractalitySpring<T>)
	return self.internal:getGoal()
end

--[=[
	@within FractalitySpring
	@method setDampingRatio

	Sets the spring's damping ratio.

	@param dampingRatio number
]=]
function FractalitySpringClass.setDampingRatio<T>(self: FractalitySpring<T>, dampingRatio: number)
	self.internal:setDampingRatio(dampingRatio)
end

--[=[
	@within FractalitySpring
	@method setFrequency

	Sets the spring's frequency.

	@param frequency number
]=]
function FractalitySpringClass.setFrequency<T>(self: FractalitySpring<T>, frequency: number)
	self.internal:setFrequency(frequency)
end

--[=[
	@within FractalitySpring
	@method setPosition

	Sets the spring's position.

	@param position T
]=]
function FractalitySpringClass.setPosition<T>(self: FractalitySpring<T>, position: T)
	self.internal:setPosition(position)
end

--[=[
	@within FractalitySpring
	@method setVelocity

	Sets the spring's velocity. The length of this array depends on the value type of the spring.

	@param velocity { number }
]=]
function FractalitySpringClass.setVelocity<T>(self: FractalitySpring<T>, velocity: { number })
	self.internal:setVelocity(velocity)
end

--[=[
	@within FractalitySpring
	@method setGoal

	Sets the spring's goal.

	@param goal T
]=]
function FractalitySpringClass.setGoal<T>(self: FractalitySpring<T>, goal: T)
	self.internal:setGoal(goal)
end

--[=[
	@within FractalitySpring
	@method canSleep

	Provides whether or not the spring can be considered moving or not.

	@return boolean -- if true then the spring is not moving.
]=]
function FractalitySpringClass.canSleep<T>(self: FractalitySpring<T>)
	return self.internal:canSleep()
end

--[=[
	@within FractalitySpring
	@method step

	Steps the spring forward and returns the newly calculated position.

	@param dt number -- the delta-time between last step
	@return T
]=]
function FractalitySpringClass.step<T>(self: FractalitySpring<T>, dt: number)
	return self.internal:step(dt)
end

--

return FractalitySpringClass

--!strict

local LinearSpring = require(script.Parent.Primitives.LinearSpring)
local Conversion = require(script.Conversion)

-- Class

local RbxLinearSpringClass = {}
RbxLinearSpringClass.__index = RbxLinearSpringClass
RbxLinearSpringClass.ClassName = "RbxLinearSpring"

export type Supported = Conversion.Supported

export type RbxLinearSpring<T> = typeof(setmetatable(
	{} :: {
		metaType: string,
		converter: Conversion.Converter<T>,
		internal: LinearSpring.LinearSpring,
	},
	RbxLinearSpringClass
))

-- Constructors

function RbxLinearSpringClass.new<T>(dampingRatio: number, frequency: number, position: T & Supported, goal: T & Supported)
	local self = setmetatable({}, RbxLinearSpringClass) :: RbxLinearSpring<T>

	self.metaType = typeof(position)
	self.converter = Conversion[self.metaType]

	local convertedPosition = self.converter.serialize(position)
	local convertedGoal = self.converter.serialize(goal)

	self.internal = LinearSpring.new(dampingRatio, frequency, convertedPosition, convertedGoal)

	return self
end

-- Public Methods

function RbxLinearSpringClass.getDampingRatio<T>(self: RbxLinearSpring<T>)
	return self.internal:getDampingRatio()
end

function RbxLinearSpringClass.getFrequency<T>(self: RbxLinearSpring<T>)
	return self.internal:getFrequency()
end

function RbxLinearSpringClass.getPosition<T>(self: RbxLinearSpring<T>)
	return self.converter.deserialize(self.internal.position)
end

function RbxLinearSpringClass.getVelocity<T>(self: RbxLinearSpring<T>)
	return self.internal:getVelocity()
end

function RbxLinearSpringClass.getGoal<T>(self: RbxLinearSpring<T>)
	return self.converter.deserialize(self.internal:getGoal())
end

function RbxLinearSpringClass.setDampingRatio<T>(self: RbxLinearSpring<T>, dampingRatio: number)
	self.internal:setDampingRatio(dampingRatio)
end

function RbxLinearSpringClass.setFrequency<T>(self: RbxLinearSpring<T>, frequency: number)
	self.internal:setFrequency(frequency)
end

function RbxLinearSpringClass.setPosition<T>(self: RbxLinearSpring<T>, position: T)
	self.internal:setPosition(self.converter.serialize(position))
end

function RbxLinearSpringClass.setVelocity<T>(self: RbxLinearSpring<T>, velocity: { number })
	self.internal:setVelocity(velocity)
end

function RbxLinearSpringClass.setGoal<T>(self: RbxLinearSpring<T>, goal: T)
	self.internal:setGoal(self.converter.serialize(goal))
end

function RbxLinearSpringClass.canSleep<T>(self: RbxLinearSpring<T>)
	return self.internal:canSleep()
end

function RbxLinearSpringClass.step<T>(self: RbxLinearSpring<T>, dt: number)
	return self.converter.deserialize(self.internal:step(dt))
end

--

return RbxLinearSpringClass

--!strict

local Color3Luv = require(script.Color3Luv)

export type Converter<T> = {
	serialize: (T) -> { number },
	deserialize: ({ number }) -> T,
}

export type Supported = boolean | number | NumberRange | UDim | UDim2 | Vector2 | Vector3 | Color3

local Conversion = {}

-- Data types

Conversion.boolean = {
	serialize = function(value)
		return if value then { 1 } else { 0 }
	end,
	deserialize = function(value)
		return value[1] >= 0.5
	end,
} :: Converter<boolean>

Conversion.number = {
	serialize = function(value)
		return { value }
	end,
	deserialize = function(value)
		return value[1]
	end,
} :: Converter<number>

Conversion.NumberRange = {
	serialize = function(value)
		return { value.Min, value.Max }
	end,
	deserialize = function(value)
		return NumberRange.new(value[1], value[2])
	end,
} :: Converter<NumberRange>

Conversion.UDim = {
	serialize = function(value)
		return { value.Scale, value.Offset }
	end,
	deserialize = function(value)
		return UDim.new(value[1], value[2])
	end,
} :: Converter<UDim>

Conversion.UDim2 = {
	serialize = function(value)
		return { value.X.Scale, value.X.Offset, value.Y.Scale, value.Y.Offset }
	end,
	deserialize = function(value)
		return UDim2.new(value[1], value[2], value[3], value[4])
	end,
} :: Converter<UDim2>

Conversion.Vector2 = {
	serialize = function(value)
		return { value.X, value.Y }
	end,
	deserialize = function(value)
		return Vector2.new(value[1], value[2])
	end,
} :: Converter<Vector2>

Conversion.Vector3 = {
	serialize = function(value)
		return { value.X, value.Y, value.Z }
	end,
	deserialize = function(value)
		return Vector3.new(value[1], value[2], value[3])
	end,
} :: Converter<Vector3>

Conversion.Color3 = {
	serialize = Color3Luv.rgbToLuv,
	deserialize = Color3Luv.luvToRgb,
} :: Converter<Color3>

--

return Conversion
